// recipeSeverityKey — подпись severity порога: пустое значение RuleSpec
// наследует дефолт источника metric-инцидентов — warning (см. ruleSeverity,
// escalation/evaluator).
func recipeSeverityKey(severity string) string {
	if severity == "critical" {
		return "severity.critical"
	}
	return "severity.warning"
}

// recipeRuleCondition — условие порога в нотации страницы алертов метрик:
// «agg > 80» (fmtFloat/comparatorSymbol — те же, что в metricalerts.templ).
func recipeRuleCondition(s recipes.RuleSpec) string {
	return s.Agg + " " + comparatorSymbol(s.Comparator) + " " + fmtFloat(s.Threshold)
}

// recipeRuleMetricLabel — имя метрики порога с опциональным матчером
// («nginx.connections_current{state=active}»).
func recipeRuleMetricLabel(s recipes.RuleSpec) string {
	if s.LabelKey == "" {
		return s.Metric
	}
	return s.Metric + "{" + s.LabelKey + "=" + s.LabelValue + "}"
}

